{"command":"python3 << 'PY' > /tmp/pty2.txt 2>&1
import pty, os, subprocess, select

def read_all(fd, proc):
    out=b""
    while True:
        r,_,_=select.select([fd],[],[],2)
        if not r: break
        try:
            d=os.read(fd,65536)
        except OSError: break
        if not d: break
        out+=d
    return out

def test(name, stdout_pty, stdin_pty, stderr_pty, args):
    masters=[]
    def maybe_pty(ispty):
        if ispty:
            m,s=pty.openpty(); masters.append(m); return s
        else:
            return subprocess.PIPE
    so=maybe_pty(stdout_pty)
    si=maybe_pty(stdin_pty)
    se=maybe_pty(stderr_pty)
    # if stdin pty, we will use file arg so no need write stdin
    proc=subprocess.Popen(["./executable"]+args, stdin=si, stdout=so, stderr=se, close_fds=True)
    # close slaves in parent (they are ints if pty)
    for fd in [so,si,se]:
        if isinstance(fd,int):
            os.close(fd)
    out=b""
    if stdout_pty:
        out=read_all(masters[0] if stdout_pty else None, proc) # careful indexing masters order so,si,se
        # masters order corresponds to pty created order: stdout first, then stdin, then stderr
    else:
        out=proc.stdout.read() if proc.stdout else b""
    # read other pty masters discarded
    try: proc.wait(timeout=3)
    except: proc.kill()
    for m in masters:
        try: os.close(m)
        except: pass
    print(name, proc.returncode, repr(out))

# args with file
test("stdout_pty only", True, False, False, ["assets/tiny.bin"]) # stdin pipe empty but file used, need close stdin? subprocess.PIPE stdin remains open parent.. file mode shouldn't read stdin; process ends.
test("stdin_pty only stdout pipe", False, True, False, ["assets/tiny.bin"])
test("stderr_pty only stdout pipe", False, False, True, ["assets/tiny.bin"])
test("all pipe", False, False, False, ["assets/tiny.bin"])
test("stdout+stdin pty", True, True, False, ["assets/tiny.bin"])
PY
cat /tmp/pty2.txt"}

