import pty, os, subprocess, select, time
def run(stdout_pty=False, stdin_pty=False, stderr_pty=False):
    fds={}
    masters={}
    slaves={}
    for name, want in [("out",stdout_pty),("in",stdin_pty),("err",stderr_pty)]:
        if want:
            m,s=pty.openpty(); masters[name]=m; slaves[name]=s
        else:
            slaves[name]=subprocess.PIPE
    # ensure pty slave for stdin: need keep master open
    proc=subprocess.Popen(["./executable","assets/tiny.bin"], stdin=slaves["in"], stdout=slaves["out"], stderr=slaves["err"])
    # close slave copies
    for name,s in slaves.items():
        if isinstance(s,int): os.close(s)
    out=b""
    if stdout_pty:
        m=masters["out"]
        while True:
            r,_,_=select.select([m],[],[],2)
            if not r: break
            try: d=os.read(m,65536)
            except: break
            if not d: break
            out+=d
    else:
        out=proc.stdout.read()
    proc.wait(timeout=3)
    # drain others ignored
    print(f"out_pty={stdout_pty} in_pty={stdin_pty} err_pty={stderr_pty} -> {out!r}")
    for m in masters.values():
        try: os.close(m)
        except: pass

run(True,False,False)
run(False,True,False)
run(False,False,True)
run(False,False,False)
