#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Cursor;

    #[test]
    fn columns_default_to_ten() {
        assert_eq!(parse_columns(None).unwrap(), 10);
        assert_eq!(parse_columns(Some(&"3".to_owned())).unwrap(), 3);
    }

    #[test]
    fn requested_length_is_parsed() {
        assert_eq!(parse_requested_length(None).unwrap(), None);
        assert_eq!(
            parse_requested_length(Some(&"12".to_owned())).unwrap(),
            Some(12)
        );
    }

    #[test]
    fn reading_can_be_limited() {
        let mut input = Cursor::new(b"abcdef".to_vec());
        assert_eq!(read_requested(&mut input, Some(3)).unwrap(), b"abc");

        let mut input = Cursor::new(b"abcdef".to_vec());
        assert_eq!(read_requested(&mut input, Some(0)).unwrap(), b"abcdef");

        let mut input = Cursor::new(b"abcdef".to_vec());
        assert_eq!(read_requested(&mut input, None).unwrap(), b"abcdef");
    }

    #[test]
    fn bytes_are_formatted_in_each_radix() {
        assert_eq!(format_byte(65, "x", true), "0x41");
        assert_eq!(format_byte(65, "X", false), "41");
        assert_eq!(format_byte(65, "o", true), "0o0101");
        assert_eq!(format_byte(65, "b", false), "01000001");
        assert_eq!(format_byte(255, "X", true), "0xFF");
    }

    #[test]
    fn text_column_uses_dots_for_non_printable_bytes() {
        assert_eq!(text_char(0), '.');
        assert_eq!(text_char(31), '.');
        assert_eq!(text_char(32), ' ');
        assert_eq!(text_char(126), '~');
        assert_eq!(text_char(127), '.');
        assert_eq!(text_char(255), '.');
    }

    #[test]
    fn colour_zero_is_remapped() {
        assert_eq!(colourise("x", 0, true), "\u{1b}[38;5;22mx\u{1b}[0m");
        assert_eq!(colourise("x", 65, true), "\u{1b}[38;5;65mx\u{1b}[0m");
        assert_eq!(colourise("x", 65, false), "x");
    }
}
